// Server-side localized city name lookup.
// Data files live in data/city-names/<locale>.json (generated by scripts/build-city-names.mjs).
import { readFileSync } from "node:fs";
import path from "node:path";
import { isLocale } from "@/i18n/routing";

const cache = new Map<string, Record<string, string>>();

function load(locale: string): Record<string, string> {
  if (cache.has(locale)) return cache.get(locale)!;
  try {
    const p = path.join(process.cwd(), "data", "city-names", `${locale}.json`);
    const data = JSON.parse(readFileSync(p, "utf8"));
    cache.set(locale, data);
    return data;
  } catch {
    cache.set(locale, {});
    return {};
  }
}

/** Localized city name, falling back to English then the provided fallback. */
export function cityName(code: string, locale: string, fallback?: string): string {
  const loc = isLocale(locale) ? locale : "en";
  const data = load(loc);
  if (data[code]) return data[code];
  if (loc !== "en") {
    const en = load("en");
    if (en[code]) return en[code];
  }
  return fallback ?? code;
}
